<script setup lang="ts">
import {ref,onMounted} from 'vue';
import FeedbackThread from './FeedbackThread.vue';
import {feedbackAuthor} from '../platform/feedback-profile.ts';
import {feedbackCall,type FeedbackIdentity} from '../platform/feedback.ts';
const props=defineProps<{accountLinked?:boolean}>();
const identity=ref<FeedbackIdentity>(),email=ref(''),code=ref(''),challenge=ref(''),busy=ref(false),error=ref(''),note=ref(''),retryAt=ref(0);
const health=ref<{mailConfigured:boolean;allowUnverified:boolean}>(),upgrading=ref(false);
async function status(){try{identity.value=await feedbackCall<FeedbackIdentity>('status');email.value=identity.value.email;health.value=await feedbackCall('health');}catch(exc){error.value=(exc as Error).message;}}
async function start(){busy.value=true;error.value='';try{if(health.value?.allowUnverified&&!health.value.mailConfigured){identity.value=await feedbackCall<FeedbackIdentity>('openDevice',{email:email.value});return;}const value=await feedbackCall<{challenge:string;retryAfter:number}>('verifyStart',{email:email.value});challenge.value=value.challenge;retryAt.value=Date.now()+value.retryAfter*1000;note.value='验证码已安排发送，请查收邮箱及垃圾邮件文件夹，10 分钟内有效。';}catch(exc){error.value=(exc as Error).message;}finally{busy.value=false;}}
async function verify(){busy.value=true;error.value='';try{identity.value=await feedbackCall<FeedbackIdentity>('verifyFinish',{challenge:challenge.value,code:code.value});code.value='';upgrading.value=false;}catch(exc){error.value=(exc as Error).message;}finally{busy.value=false;}}
async function change(){try{identity.value=await feedbackCall<FeedbackIdentity>('resetIdentity');challenge.value='';note.value='';}catch(exc){error.value=(exc as Error).message;}}
onMounted(status);
</script>
<template>
<div class="feedback-panel" :class="{connected:identity?.connected&&!upgrading}">
  <template v-if="identity?.connected&&!upgrading"><div class="feedback-identity"><span>{{identity.email}} <small class="muted">{{identity.verified?'已验证':'联系邮箱未验证'}}</small></span><button v-if="identity.verified&&!accountLinked" @click="change">切换邮箱</button><button v-else-if="!accountLinked&&health?.mailConfigured" @click="upgrading=true;error=''">验证联系邮箱</button></div><FeedbackThread :owner="identity.owner"/></template>
  <section v-else-if="accountLinked" class="feedback-verification"><h3>问题反馈</h3><p class="muted">{{error||'正在连接当前账号的反馈会话…'}}</p><button v-if="error" @click="status">重试连接</button></section>
  <form v-else class="feedback-verification" @submit.prevent="challenge?verify():start()"><div class="verification-author"><img :src="feedbackAuthor.avatar" :alt="feedbackAuthor.name+'的头像'"/><strong>{{feedbackAuthor.name}}</strong><span class="muted">问题反馈</span></div><h3>{{health?.allowUnverified&&!health.mailConfigured?'留下联系邮箱，开始反馈':'首次反馈，验证邮箱'}}</h3><p class="muted">无需注册账号或设置密码。回复会保存在应用中，进入会话后可选择是否接收邮件提醒。</p><p v-if="health?.allowUnverified&&!health.mailConfigured" class="muted">邮箱通知暂未开放，井韶子可按此邮箱手动联系您。会话保存在当前设备的反馈身份中，清除应用数据或丢失凭据后暂不支持仅凭邮箱恢复。</p><label>邮箱地址<input v-model="email" type="email" autocomplete="email" required maxlength="254" :disabled="busy||!!challenge||upgrading" placeholder="name@example.com"/></label><template v-if="challenge"><label>邮箱验证码<input v-model="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required placeholder="6 位验证码"/></label><p class="muted" role="status">{{note}}</p></template><p v-if="error" class="feedback-error" role="alert">{{error}}</p><div class="verification-actions"><button class="primary" :disabled="busy||!health">{{busy?'正在处理…':challenge?'验证并进入会话':health?.allowUnverified&&!health.mailConfigured?'进入反馈会话':'发送验证码'}}</button><button v-if="upgrading" type="button" :disabled="busy" @click="upgrading=false;challenge='';code='';error=''">返回会话</button><button v-if="!health" type="button" @click="status">重试连接</button><button v-if="challenge&&!upgrading" type="button" :disabled="busy" @click="challenge='';code='';note=''">更换邮箱</button><button v-if="challenge" type="button" :disabled="busy" @click="Date.now()>=retryAt?start():error='请等待 60 秒后重新发送验证码。'">重新发送</button></div><small>服务器保存邮箱、反馈文字和图片。应用不会自动上传录音、工程或电脑中的其他文件。</small></form>
</div>
</template>
<style scoped>
.feedback-panel{display:flex;flex-direction:column;gap:16px;min-width:0}.feedback-panel.connected{height:min(65vh,680px);min-height:300px}.feedback-identity{display:flex;align-items:center;justify-content:space-between;gap:10px}.feedback-verification{width:100%;max-width:560px;margin:0 auto;display:flex;flex-direction:column;gap:18px}.feedback-verification h3{font-size:1.35rem;margin:6px 0 0}.feedback-verification p{margin:0;line-height:1.8}.feedback-verification>small{font-size:.8rem;line-height:1.75;color:var(--muted);border-top:1px solid var(--border);padding-top:16px}.feedback-verification input{min-height:42px}.verification-actions button{min-height:40px}.feedback-identity{font-size:.85rem;flex-wrap:wrap}.feedback-verification label{display:flex;flex-direction:column;gap:6px}.verification-actions{display:flex;gap:8px;flex-wrap:wrap}.feedback-error{color:var(--danger)}.verification-author{display:flex;align-items:center;gap:10px}.verification-author img{width:46px;height:46px;object-fit:cover;object-position:50% 32%;border-radius:50%;border:1px solid var(--border)}.verification-author span{font-size:.8rem}
</style>
